test "test_drop_removes_the_top_value_on_the_stack_if_it_is_the_only_one" {const result=try m.evaluate(a,&.{"1 drop"});defer a.free(result);try t.expectEqualSlices(i64,&.{},result);}
test "test_drop_removes_the_top_value_on_the_stack_if_it_is_not_the_only_one" {const result=try m.evaluate(a,&.{"1 2 drop"});defer a.free(result);try t.expectEqualSlices(i64,&.{1},result);}
test "test_drop_errors_if_there_is_nothing_on_the_stack" {try t.expectError(error.StackUnderflow,m.evaluate(a,&.{"drop"}));}
test "test_swap_swaps_the_top_two_values_on_the_stack_if_they_are_the_only_ones" {const result=try m.evaluate(a,&.{"1 2 swap"});defer a.free(result);try t.expectEqualSlices(i64,&.{2,1},result);}
test "test_swap_swaps_the_top_two_values_on_the_stack_if_they_are_not_the_only_ones" {const result=try m.evaluate(a,&.{"1 2 3 swap"});defer a.free(result);try t.expectEqualSlices(i64,&.{1,3,2},result);}
test "test_swap_errors_if_there_is_nothing_on_the_stack" {try t.expectError(error.StackUnderflow,m.evaluate(a,&.{"swap"}));}
test "test_swap_errors_if_there_is_only_one_value_on_the_stack" {try t.expectError(error.StackUnderflow,m.evaluate(a,&.{"1 swap"}));}
test "test_over_copies_the_second_element_if_there_are_only_two" {const result=try m.evaluate(a,&.{"1 2 over"});defer a.free(result);try t.expectEqualSlices(i64,&.{1,2,1},result);}
test "test_over_copies_the_second_element_if_there_are_more_than_two" {const result=try m.evaluate(a,&.{"1 2 3 over"});defer a.free(result);try t.expectEqualSlices(i64,&.{1,2,3,2},result);}
test "test_over_errors_if_there_is_nothing_on_the_stack" {try t.expectError(error.StackUnderflow,m.evaluate(a,&.{"over"}));}
test "test_over_errors_if_there_is_only_one_value_on_the_stack" {try t.expectError(error.StackUnderflow,m.evaluate(a,&.{"1 over"}));}
test "test_user_defined_words_can_consist_of_built_in_words" {const result=try m.evaluate(a,&.{": dup-twice dup dup ;","1 dup-twice"});defer a.free(result);try t.expectEqualSlices(i64,&.{1,1,1},result);}
test "test_user_defined_words_execute_in_the_right_order" {const result=try m.evaluate(a,&.{": countup 1 2 3 ;","countup"});defer a.free(result);try t.expectEqualSlices(i64,&.{1,2,3},result);}
test "test_user_defined_words_can_override_other_user_defined_words" {const result=try m.evaluate(a,&.{": foo dup ;",": foo dup dup ;","1 foo"});defer a.free(result);try t.expectEqualSlices(i64,&.{1,1,1},result);}
test "test_user_defined_words_can_override_built_in_words" {const result=try m.evaluate(a,&.{": swap dup ;","1 swap"});defer a.free(result);try t.expectEqualSlices(i64,&.{1,1},result);}
test "test_user_defined_words_can_override_built_in_operators" {const result=try m.evaluate(a,&.{": + * ;","3 4 +"});defer a.free(result);try t.expectEqualSlices(i64,&.{12},result);}
test "test_user_defined_words_can_use_different_words_with_the_same_name" {const result=try m.evaluate(a,&.{": foo 5 ;",": bar foo ;",": foo 6 ;","bar foo"});defer a.free(result);try t.expectEqualSlices(i64,&.{5,6},result);}
test "test_user_defined_words_can_define_word_that_uses_word_with_the_same_name" {const result=try m.evaluate(a,&.{": foo 10 ;",": foo foo 1 + ;","foo"});defer a.free(result);try t.expectEqualSlices(i64,&.{11},result);}
test "test_user_defined_words_cannot_redefine_non_negative_numbers" {try t.expectError(error.IllegalDefinition,m.evaluate(a,&.{": 1 2 ;"}));}
test "test_user_defined_words_cannot_redefine_negative_numbers" {try t.expectError(error.IllegalDefinition,m.evaluate(a,&.{": -1 2 ;"}));}
test "test_user_defined_words_errors_if_executing_a_non_existent_word" {try t.expectError(error.UndefinedOperation,m.evaluate(a,&.{"foo"}));}
test "test_case_insensitivity_dup_is_case_insensitive" {const result=try m.evaluate(a,&.{"1 DUP Dup dup"});defer a.free(result);try t.expectEqualSlices(i64,&.{1,1,1,1},result);}
test "test_case_insensitivity_drop_is_case_insensitive" {const result=try m.evaluate(a,&.{"1 2 3 4 DROP Drop drop"});defer a.free(result);try t.expectEqualSlices(i64,&.{1},result);}
test "test_case_insensitivity_swap_is_case_insensitive" {const result=try m.evaluate(a,&.{"1 2 SWAP 3 Swap 4 swap"});defer a.free(result);try t.expectEqualSlices(i64,&.{2,3,4,1},result);}
test "test_case_insensitivity_over_is_case_insensitive" {const result=try m.evaluate(a,&.{"1 2 OVER Over over"});defer a.free(result);try t.expectEqualSlices(i64,&.{1,2,1,2,1},result);}
test "test_case_insensitivity_user_defined_words_are_case_insensitive" {const result=try m.evaluate(a,&.{": foo dup ;","1 FOO Foo foo"});defer a.free(result);try t.expectEqualSlices(i64,&.{1,1,1,1},result);}
test "test_case_insensitivity_definitions_are_case_insensitive" {const result=try m.evaluate(a,&.{": SWAP DUP Dup dup ;","1 swap"});defer a.free(result);try t.expectEqualSlices(i64,&.{1,1,1,1},result);}
